package com.spoonmeter;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * One page of the collection log as it was last seen: its counters and the uniques already
 * obtained. Only obtained items are stored; anything missing is worked out from the drop table,
 * which keeps the saved file small and stops it going stale when Jagex adds items to a page.
 */
public class CollectionLogPage
{
	private String name;
	private int obtained;
	private int total;
	private Map<String, Integer> counters = new LinkedHashMap<>();
	private Map<String, Integer> items = new LinkedHashMap<>();
	private long updatedMillis;

	public CollectionLogPage()
	{
	}

	public CollectionLogPage(String name)
	{
		this.name = name;
	}

	public String getName()
	{
		return name;
	}

	public void setName(String name)
	{
		this.name = name;
	}

	public int getObtained()
	{
		return obtained;
	}

	public void setObtained(int obtained)
	{
		this.obtained = obtained;
	}

	public int getTotal()
	{
		return total;
	}

	public void setTotal(int total)
	{
		this.total = total;
	}

	public Map<String, Integer> getCounters()
	{
		return counters;
	}

	public void setCounters(Map<String, Integer> counters)
	{
		this.counters = counters == null ? new LinkedHashMap<>() : counters;
	}

	public Map<String, Integer> getItems()
	{
		return items;
	}

	public void setItems(Map<String, Integer> items)
	{
		this.items = items == null ? new LinkedHashMap<>() : items;
	}

	public long getUpdatedMillis()
	{
		return updatedMillis;
	}

	public void setUpdatedMillis(long updatedMillis)
	{
		this.updatedMillis = updatedMillis;
	}

	/**
	 * The counter the rating is based on. Pages can show several ("Kill count", "Chest opened",
	 * "Reward permit"); the largest is the one that actually generated the drop rolls.
	 */
	public int getPrimaryCount()
	{
		int best = 0;

		for (int value : counters.values())
		{
			best = Math.max(best, value);
		}

		return best;
	}

	public String getPrimaryCounterLabel()
	{
		String label = null;
		int best = -1;

		for (Map.Entry<String, Integer> entry : counters.entrySet())
		{
			if (entry.getValue() > best)
			{
				best = entry.getValue();
				label = entry.getKey();
			}
		}

		return label == null ? "Kill count" : label;
	}

	/**
	 * Value of a named counter, matched loosely so that "Corrupted Gauntlet completion count"
	 * survives punctuation and case differences. 0 when the page has no such counter.
	 */
	public int counterValue(String label)
	{
		String wanted = DropTable.normaliseCounter(label);

		for (Map.Entry<String, Integer> entry : counters.entrySet())
		{
			if (DropTable.normaliseCounter(entry.getKey()).equals(wanted))
			{
				return entry.getValue();
			}
		}

		return 0;
	}

	/** Total number of a given item obtained, matched on the normalised name. */
	public int quantityOf(String itemName)
	{
		String wanted = DropTable.normalise(itemName);

		for (Map.Entry<String, Integer> entry : items.entrySet())
		{
			if (DropTable.normalise(entry.getKey()).equals(wanted))
			{
				return entry.getValue();
			}
		}

		return 0;
	}

	/** Combined quantity of every item in a group that shares one drop slot. */
	public int quantityOfAny(java.util.List<String> itemNames)
	{
		int total = 0;

		for (String itemName : itemNames)
		{
			total += quantityOf(itemName);
		}

		return total;
	}

	/** Cheap fingerprint used to skip re-saving a page that has not changed since the last tick. */
	public String fingerprint()
	{
		return name + "|" + obtained + "/" + total + "|" + counters + "|" + items;
	}
}

package com.spoonmeter;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.annotation.Nullable;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

/**
 * Reads whichever collection log page is currently on screen.
 *
 * <p>Deliberately structural rather than hardcoded to child indices: it walks the interface looking
 * for the "Obtained: x/y" line to identify the header, and for the widget holding the most item
 * children to identify the item grid. Jagex reshuffles these child ids from time to time, and this
 * survives that.
 */
class CollectionLogParser
{
	static final int COLLECTION_LOG_GROUP_ID = 621;

	private static final int MAX_ROOT_CHILDREN = 100;
	private static final int MAX_DEPTH = 8;

	private static final Pattern OBTAINED = Pattern.compile("^Obtained:\\s*(\\d+)\\s*/\\s*(\\d+)$");

	// The label deliberately cannot contain a colon. Pages also show personal best times such as
	// "Personal Best: 9:51", and a looser pattern reads those as a counter named "Personal Best: 9"
	// with a value of 51 - which then beats the real kill count on any page with a low KC.
	private static final Pattern COUNTER = Pattern.compile("^([^:]+):\\s*([\\d,]+)$");

	private final ItemManager itemManager;

	CollectionLogParser(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	boolean isLogOpen(Client client)
	{
		for (int childId = 0; childId < MAX_ROOT_CHILDREN; childId++)
		{
			if (client.getWidget(COLLECTION_LOG_GROUP_ID, childId) != null)
			{
				return true;
			}
		}

		return false;
	}

	/**
	 * @return the page currently displayed, or null if the log is closed or no page is selected.
	 */
	@Nullable
	CollectionLogPage parseOpenPage(Client client)
	{
		Scan scan = new Scan();

		for (int childId = 0; childId < MAX_ROOT_CHILDREN; childId++)
		{
			Widget root = client.getWidget(COLLECTION_LOG_GROUP_ID, childId);

			if (root != null)
			{
				walk(root, 0, scan);
			}
		}

		if (scan.header == null || scan.itemContainer == null)
		{
			return null;
		}

		CollectionLogPage page = readHeader(scan.header);

		if (page == null)
		{
			return null;
		}

		page.setItems(readItems(scan.itemContainer));
		page.setUpdatedMillis(System.currentTimeMillis());
		return page;
	}

	private void walk(Widget widget, int depth, Scan scan)
	{
		if (widget == null || depth > MAX_DEPTH)
		{
			return;
		}

		List<Widget> children = childrenOf(widget);

		if (!children.isEmpty())
		{
			int itemCount = 0;

			for (Widget child : children)
			{
				if (child.getItemId() > 0)
				{
					itemCount++;
				}

				String text = Text.removeTags(nullToEmpty(child.getText()));

				if (OBTAINED.matcher(text).matches())
				{
					scan.header = widget;
				}
			}

			// The item grid is the one widget on the page holding a wall of items; the tab list and
			// header hold at most a handful, so "most items wins" is a safe way to pick it out.
			if (itemCount > scan.itemCount)
			{
				scan.itemCount = itemCount;
				scan.itemContainer = widget;
			}
		}

		for (Widget child : children)
		{
			walk(child, depth + 1, scan);
		}
	}

	@Nullable
	private CollectionLogPage readHeader(Widget header)
	{
		List<Widget> children = childrenOf(header);

		String title = null;
		int obtainedIndex = -1;
		int obtained = 0;
		int total = 0;
		Map<String, Integer> counters = new LinkedHashMap<>();

		for (int i = 0; i < children.size(); i++)
		{
			String text = Text.removeTags(nullToEmpty(children.get(i).getText())).trim();

			if (text.isEmpty())
			{
				continue;
			}

			Matcher obtainedMatcher = OBTAINED.matcher(text);

			if (obtainedMatcher.matches())
			{
				obtainedIndex = i;
				obtained = parseInt(obtainedMatcher.group(1));
				total = parseInt(obtainedMatcher.group(2));
				continue;
			}

			if (obtainedIndex < 0)
			{
				// Anything before the "Obtained" line is the page title.
				if (title == null)
				{
					title = text;
				}

				continue;
			}

			addCounter(counters, text);
		}

		if (title == null || obtainedIndex < 0)
		{
			return null;
		}

		CollectionLogPage page = new CollectionLogPage(title);
		page.setObtained(obtained);
		page.setTotal(total);
		page.setCounters(counters);
		return page;
	}

	/**
	 * Records a "Label: 1,234" header line as a counter.
	 *
	 * @return false if the line is not a counter at all, such as a "Personal Best: 9:51" time
	 */
	static boolean addCounter(Map<String, Integer> counters, String text)
	{
		Matcher matcher = COUNTER.matcher(text);

		if (!matcher.matches())
		{
			return false;
		}

		counters.put(matcher.group(1).trim(), parseInt(matcher.group(2)));
		return true;
	}

	private Map<String, Integer> readItems(Widget container)
	{
		Map<String, Integer> items = new LinkedHashMap<>();

		for (Widget child : childrenOf(container))
		{
			int itemId = child.getItemId();

			if (itemId <= 0)
			{
				continue;
			}

			// Unobtained entries are drawn faded; obtained ones are fully opaque.
			if (child.getOpacity() != 0)
			{
				continue;
			}

			String name = Text.removeTags(nullToEmpty(child.getName())).trim();

			if (name.isEmpty() && itemManager != null)
			{
				name = itemManager.getItemComposition(itemId).getName();
			}

			if (name.isEmpty())
			{
				continue;
			}

			int quantity = Math.max(1, child.getItemQuantity());
			items.merge(name, quantity, Integer::sum);
		}

		return items;
	}

	private static List<Widget> childrenOf(Widget widget)
	{
		List<Widget> out = new ArrayList<>();
		addAll(out, widget.getStaticChildren());
		addAll(out, widget.getDynamicChildren());
		addAll(out, widget.getNestedChildren());
		return out;
	}

	private static void addAll(List<Widget> out, @Nullable Widget[] widgets)
	{
		if (widgets == null)
		{
			return;
		}

		for (Widget widget : widgets)
		{
			if (widget != null)
			{
				out.add(widget);
			}
		}
	}

	private static int parseInt(String raw)
	{
		try
		{
			return Integer.parseInt(raw.replace(",", "").trim());
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	private static String nullToEmpty(@Nullable String s)
	{
		return s == null ? "" : s;
	}

	private static final class Scan
	{
		private Widget header;
		private Widget itemContainer;
		private int itemCount;
	}
}

package com.spoonmeter;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import net.runelite.client.util.Filepath;

/**
 * The drop rates the rating is measured against, loaded from {@code drop_rates.json}.
 *
 * <p>A source is either simple - one counter, one set of rates - or split into <b>variants</b>. One
 * collection log page can cover several activities with different rates and their own counters: the
 * Gauntlet page counts normal and corrupted runs separately at 1/120 and 1/50, the raid pages count
 * normal, entry and hard/expert completions, and the Dagannoth Kings page counts all three kings.
 * Each variant names the counter it applies to, and expectations are summed across them.
 *
 * <p>Lookups are done on normalised names so that "Kree'arra", "kreearra" and the collection log's
 * own spelling all land on the same entry, and so that item names survive the log's
 * "(uncharged)" style suffixes.
 */
public class DropTable
{
	public static final String RESOURCE = "/com/spoonmeter/drop_rates.json";

	public static class Definition
	{
		int version;
		String note;
		List<Source> sources;
	}

	public static class Source
	{
		String name;
		List<String> aliases;
		boolean approx;

		/** One page covering several different bosses, such as Callisto and Artio. */
		boolean combined;

		// Simple form: one implicit variant.
		String counter;
		String uniqueChanceKey;
		String rollsPerKcKey;
		Double totalWeight;
		List<Item> items;

		// Split form.
		List<Variant> variants;

		private transient List<Variant> effective;

		public String getName()
		{
			return name;
		}

		public boolean isApprox()
		{
			return approx;
		}

		public boolean isCombined()
		{
			return combined;
		}

		/** The split variants, or a single synthesised one for a simple source. */
		public List<Variant> getVariants()
		{
			if (effective == null)
			{
				if (variants != null && !variants.isEmpty())
				{
					effective = variants;
				}
				else
				{
					Variant single = new Variant();
					single.counter = counter;
					single.uniqueChanceKey = uniqueChanceKey;
					single.rollsPerKcKey = rollsPerKcKey;
					single.totalWeight = totalWeight;
					single.items = items;
					effective = Collections.singletonList(single);
				}
			}

			return effective;
		}

		/** Every distinct item across all variants, in table order. */
		public List<Item> getItems()
		{
			Set<String> seen = new LinkedHashSet<>();
			List<Item> out = new ArrayList<>();

			for (Variant variant : getVariants())
			{
				for (Item item : variant.getItems())
				{
					if (seen.add(normalise(item.name)))
					{
						out.add(item);
					}
				}
			}

			return out;
		}
	}

	public static class Variant
	{
		String counter;
		String uniqueChanceKey;

		/**
		 * Config key for how many times this variant is rolled per kill the log counts, where that
		 * is not simply once and the log cannot tell. The Hueycoatl needs it: its unique chance is
		 * per player and scaled by contribution, so a mass world splits one roll between everyone
		 * fighting and a share is a fraction of a roll. A source rolled several times over would
		 * use the same key the other way.
		 */
		String rollsPerKcKey;
		Double totalWeight;
		List<Item> items;

		/** Name of the page counter this variant is rolled by, or null to use the page's largest. */
		@Nullable
		public String getCounter()
		{
			return counter;
		}

		@Nullable
		public String getUniqueChanceKey()
		{
			return uniqueChanceKey;
		}

		@Nullable
		public String getRollsPerKcKey()
		{
			return rollsPerKcKey;
		}

		public List<Item> getItems()
		{
			return items == null ? Collections.emptyList() : items;
		}
	}

	public static class Item
	{
		String name;

		/**
		 * Several items sharing a single drop slot, where which one you get is decided by duplicate
		 * protection rather than by a separate roll. The brimstone ring pieces work this way: one
		 * 1/181.1 slot hands out the eye, then the fang, then the heart. Listing them as three
		 * entries would treble the real rate.
		 */
		List<String> names;
		String label;

		Double rate;
		Double weight;
		Double chance;

		/**
		 * Whether this item also comes from somewhere the collection log never counts. The log
		 * records a quantity for the whole account but counts only boss kills, so an occult
		 * necklace, which drops off ordinary smoke devils a slayer task supplies hundreds of,
		 * arrives with a number that says nothing about the boss. Such items are listed but not
		 * scored unless the player says otherwise, because the count is not evidence.
		 */
		boolean uncounted;

		/**
		 * Config key for how many times this one item is rolled per kill, where the rest of the
		 * source is not. An awakened Desert Treasure boss rolls its unique table three times as
		 * often, but the orb and the pet are rolled outside that table and are not stated to change,
		 * so the scaling cannot be applied to the whole source.
		 */
		String rollsPerKcKey;

		@Nullable
		public String getRollsPerKcKey()
		{
			return rollsPerKcKey;
		}

		public boolean isUncounted()
		{
			return uncounted;
		}

		/** What the panel shows. */
		public String getName()
		{
			if (name != null)
			{
				return name;
			}

			return label != null ? label : String.join(" / ", getNames());
		}

		/** Every item name this entry covers. */
		public List<String> getNames()
		{
			return names != null && !names.isEmpty() ? names : Collections.singletonList(name);
		}
	}

	private final List<Source> sources;
	private final Map<String, Source> byNormalisedName = new HashMap<>();

	private DropTable(List<Source> sources)
	{
		this.sources = sources;

		for (Source source : sources)
		{
			byNormalisedName.put(normalise(source.name), source);

			if (source.aliases != null)
			{
				for (String alias : source.aliases)
				{
					byNormalisedName.put(normalise(alias), source);
				}
			}
		}
	}

	/**
	 * Loads the bundled table, or the user's own copy if {@code override} exists. Letting people
	 * drop a corrected file next to their RuneLite settings means a wrong rate never needs a
	 * plugin update to fix.
	 */
	public static DropTable load(Gson gson, @Nullable Filepath override) throws IOException
	{
		if (override != null && override.isFile())
		{
			try (Reader reader = override.openBufferedReader())
			{
				return fromReader(gson, reader);
			}
		}

		try (InputStream in = DropTable.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				throw new IOException("Missing bundled drop table: " + RESOURCE);
			}

			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				return fromReader(gson, reader);
			}
		}
	}

	private static DropTable fromReader(Gson gson, Reader reader) throws IOException
	{
		Definition definition = gson.fromJson(reader, Definition.class);

		if (definition == null || definition.sources == null || definition.sources.isEmpty())
		{
			throw new IOException("Drop table is empty or malformed");
		}

		return new DropTable(new ArrayList<>(definition.sources));
	}

	public List<Source> getSources()
	{
		return Collections.unmodifiableList(sources);
	}

	@Nullable
	public Source find(String collectionLogPageName)
	{
		if (collectionLogPageName == null)
		{
			return null;
		}

		return byNormalisedName.get(normalise(collectionLogPageName));
	}

	/**
	 * Per-completion chance of a single item within one variant.
	 *
	 * @param uniqueChance chance of any unique per completion, used by the weight-based raid
	 *                     entries; ignored by entries that state a flat rate.
	 */
	public static double probability(Variant variant, Item item, double uniqueChance)
	{
		if (item.chance != null && item.chance > 0)
		{
			return item.chance;
		}

		if (item.rate != null && item.rate > 0)
		{
			return 1.0 / item.rate;
		}

		if (item.weight != null && variant.totalWeight != null && variant.totalWeight > 0)
		{
			return uniqueChance * (item.weight / variant.totalWeight);
		}

		return 0.0;
	}

	/** Item name to per-completion chance for one variant, in table order. */
	public static Map<String, Double> probabilities(Variant variant, double uniqueChance)
	{
		Map<String, Double> out = new LinkedHashMap<>();

		for (Item item : variant.getItems())
		{
			double p = probability(variant, item, uniqueChance);

			if (p > 0)
			{
				out.put(item.name, p);
			}
		}

		return out;
	}

	/**
	 * Lowercase, drop bracketed qualifiers such as "(uncharged)", and strip punctuation, so that
	 * apostrophes and the game's occasional renames do not break a lookup.
	 */
	public static String normalise(String name)
	{
		if (name == null)
		{
			return "";
		}

		String s = name.toLowerCase(Locale.ENGLISH);
		s = s.replaceAll("\\(.*?\\)", " ");
		s = s.replaceAll("[^a-z0-9 ]", "");
		s = s.replaceAll("\\s+", " ").trim();

		if (s.startsWith("the "))
		{
			s = s.substring(4);
		}

		return s;
	}

	/**
	 * Counter labels get a gentler normalisation than item names: the bracketed part is the whole
	 * distinction between "Chambers of Xeric completions" and "Chambers of Xeric (CM) completions",
	 * so brackets are unwrapped rather than dropped.
	 */
	public static String normaliseCounter(String label)
	{
		if (label == null)
		{
			return "";
		}

		String s = label.toLowerCase(Locale.ENGLISH);
		s = s.replaceAll("[^a-z0-9 ]", " ");
		return s.replaceAll("\\s+", " ").trim();
	}
}

package com.spoonmeter;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;

/**
 * A cursed-to-spooned strip with a marker at the account's percentile. Reading a percentile off a
 * bar is a lot faster than reading it off a number, and the colour does the editorialising.
 */
class LuckBar extends JComponent
{
	private static final Color CURSED = new Color(0xC62828);
	private static final Color MIDDLE = new Color(0x9E9E9E);
	private static final Color SPOONED = new Color(0xFFC107);

	private double percentile;

	LuckBar(int height)
	{
		setPreferredSize(new Dimension(0, height));
		setMinimumSize(new Dimension(0, height));
	}

	void setPercentile(double percentile)
	{
		this.percentile = Math.max(0, Math.min(1, percentile));
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();

		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

			int w = getWidth();
			int h = getHeight();
			int arc = Math.min(h, 8);

			g2.setColor(ColorScheme.DARK_GRAY_COLOR);
			g2.fillRoundRect(0, 0, w, h, arc, arc);

			g2.setPaint(new GradientPaint(0, 0, CURSED, w / 2f, 0, MIDDLE));
			g2.fillRoundRect(0, 0, w / 2, h, arc, arc);

			g2.setPaint(new GradientPaint(w / 2f, 0, MIDDLE, w, 0, SPOONED));
			g2.fillRoundRect(w / 2, 0, w - w / 2, h, arc, arc);

			int x = (int) Math.round(percentile * (w - 3));
			g2.setColor(Color.WHITE);
			g2.fillRect(x, -1, 3, h + 2);
			g2.setColor(new Color(0, 0, 0, 120));
			g2.drawRect(x, -1, 3, h + 2);
		}
		finally
		{
			g2.dispose();
		}
	}
}

package com.spoonmeter;

/**
 * The statistics behind the rating.
 *
 * <p>Every unique in a collection log page is an independent Bernoulli trial repeated once per kill,
 * so the number of uniques a player owns is the sum of many independent binomials with tiny p and
 * large n. That sum is very well approximated by a Poisson variable with
 * {@code lambda = sum(kc * p_i)}, which is what we use: it needs no per-item bookkeeping, stays
 * numerically sane at any KC, and is exact enough that the difference never moves a rating band.
 *
 * <p>"Luck" is then the mid-p percentile of your observed unique count under that Poisson: the
 * fraction of accounts with your exact KC who would have fewer uniques than you.
 */
public final class LuckCalculator
{
	private LuckCalculator()
	{
	}

	/**
	 * Fraction of accounts (0..1) at the same KC that would be doing worse than this player.
	 * 0.5 is dead average, 1.0 is spooned beyond belief, 0.0 is a war crime.
	 *
	 * <p>Uses the mid-p convention (half of the probability mass at the observed value counts as
	 * "worse") so that the score is centred on 0.5 for an average account instead of being biased
	 * upwards by the discreteness of the distribution.
	 */
	public static double luckPercentile(double lambda, int observed)
	{
		if (lambda <= 0 || observed < 0)
		{
			return 0.5;
		}

		double below = observed == 0 ? 0.0 : regularizedGammaQ(observed, lambda);
		double at = poissonPmf(observed, lambda);
		return clamp(below + 0.5 * at);
	}

	/** P(X = k) for X ~ Poisson(lambda). */
	public static double poissonPmf(int k, double lambda)
	{
		if (k < 0 || lambda < 0)
		{
			return 0.0;
		}

		if (lambda == 0)
		{
			return k == 0 ? 1.0 : 0.0;
		}

		return Math.exp(-lambda + k * Math.log(lambda) - logGamma(k + 1.0));
	}

	/** P(X &lt;= k) for X ~ Poisson(lambda). */
	public static double poissonCdf(int k, double lambda)
	{
		if (k < 0)
		{
			return 0.0;
		}

		if (lambda <= 0)
		{
			return 1.0;
		}

		return clamp(regularizedGammaQ(k + 1.0, lambda));
	}

	/**
	 * Probability of having seen at least one of an item with per-kill chance {@code p} after
	 * {@code kc} kills. Also read as "the share of players who would already have it by now",
	 * which is the number that makes a dry streak hurt.
	 */
	public static double dryness(double p, int kc)
	{
		if (p <= 0 || kc <= 0)
		{
			return 0.0;
		}

		return clamp(1.0 - Math.pow(1.0 - p, kc));
	}

	// --- incomplete gamma -----------------------------------------------------------------
	// P(X <= k) for Poisson(lambda) equals the regularized upper incomplete gamma Q(k + 1, lambda),
	// which stays accurate for large lambda where a naive term-by-term sum would drown in rounding.

	static double regularizedGammaQ(double a, double x)
	{
		if (x <= 0)
		{
			return 1.0;
		}

		if (a <= 0)
		{
			return 0.0;
		}

		return x < a + 1.0 ? 1.0 - gammaSeries(a, x) : gammaContinuedFraction(a, x);
	}

	/** Series expansion for the regularized lower incomplete gamma P(a, x); converges fast for x < a+1. */
	private static double gammaSeries(double a, double x)
	{
		double ap = a;
		double sum = 1.0 / a;
		double del = sum;

		for (int n = 0; n < 10000; n++)
		{
			ap += 1.0;
			del *= x / ap;
			sum += del;

			if (Math.abs(del) < Math.abs(sum) * 1.0e-15)
			{
				break;
			}
		}

		return sum * Math.exp(-x + a * Math.log(x) - logGamma(a));
	}

	/** Lentz's modified continued fraction for Q(a, x); converges fast for x >= a+1. */
	private static double gammaContinuedFraction(double a, double x)
	{
		final double tiny = 1.0e-300;

		double b = x + 1.0 - a;
		double c = 1.0 / tiny;
		double d = 1.0 / b;
		double h = d;

		for (int i = 1; i < 10000; i++)
		{
			double an = -i * (i - a);
			b += 2.0;

			d = an * d + b;
			if (Math.abs(d) < tiny)
			{
				d = tiny;
			}

			c = b + an / c;
			if (Math.abs(c) < tiny)
			{
				c = tiny;
			}

			d = 1.0 / d;
			double del = d * c;
			h *= del;

			if (Math.abs(del - 1.0) < 1.0e-15)
			{
				break;
			}
		}

		return h * Math.exp(-x + a * Math.log(x) - logGamma(a));
	}

	/** Lanczos approximation, good to ~15 significant digits for x > 0. */
	static double logGamma(double x)
	{
		final double[] coefficients = {
			76.18009172947146, -86.50532032941677, 24.01409824083091,
			-1.231739572450155, 0.1208650973866179e-2, -0.5395239384953e-5
		};

		double y = x;
		double tmp = x + 5.5;
		tmp -= (x + 0.5) * Math.log(tmp);

		double ser = 1.000000000190015;
		for (double coefficient : coefficients)
		{
			ser += coefficient / ++y;
		}

		return -tmp + Math.log(2.5066282746310005 * ser / x);
	}

	private static double clamp(double v)
	{
		if (Double.isNaN(v))
		{
			return 0.5;
		}

		return Math.max(0.0, Math.min(1.0, v));
	}
}

package com.spoonmeter;

import java.awt.Color;

/**
 * The verdict bands. Each covers a slice of the luck percentile, from "the drop table loves you"
 * down to "the drop table has personally wronged you".
 */
public enum LuckRating
{
	SPOONED_BY_THE_GODS(0.99, "Spooned by the Gods", new Color(0xFFD700), "Top 1%. Please stop."),
	ABSOLUTELY_SPOONED(0.95, "Absolutely Spooned", new Color(0xFFB300), "You have been handed things."),
	SPOONED(0.85, "Spooned", new Color(0x8BE28B), "Comfortably ahead of rate."),
	BLESSED(0.65, "Blessed", new Color(0x5DBB63), "A quietly lucky account."),
	AVERAGE(0.35, "Painfully Average", new Color(0xC8C8C8), "Exactly what the wiki promised."),
	A_BIT_DRY(0.15, "A Bit Dry", new Color(0xE0A030), "Behind rate, but survivable."),
	CURSED(0.05, "Cursed", new Color(0xFF7043), "The drop table is ignoring you."),
	HARD_CURSED(0.01, "Hard Cursed", new Color(0xE53935), "Bottom 5%. Genuinely unlucky."),
	RNG_HATES_YOU(0.0, "RNG Hates You", new Color(0xC2185B), "Bottom 1%. Consider a new hobby.");

	private final double minPercentile;
	private final String title;
	private final Color color;
	private final String blurb;

	LuckRating(double minPercentile, String title, Color color, String blurb)
	{
		this.minPercentile = minPercentile;
		this.title = title;
		this.color = color;
		this.blurb = blurb;
	}

	public String getTitle()
	{
		return title;
	}

	public Color getColor()
	{
		return color;
	}

	public String getBlurb()
	{
		return blurb;
	}

	public double getMinPercentile()
	{
		return minPercentile;
	}

	public static LuckRating fromPercentile(double percentile)
	{
		for (LuckRating rating : values())
		{
			if (percentile >= rating.minPercentile)
			{
				return rating;
			}
		}

		return RNG_HATES_YOU;
	}

	/** 0-100 "spoon score", which is just the percentile in a friendlier costume. */
	public static int spoonScore(double percentile)
	{
		return (int) Math.round(percentile * 100.0);
	}
}

package com.spoonmeter;

import java.util.Map;
import java.util.Random;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Rates a source by what it dropped, not just how much.
 *
 * <p>Counting uniques cannot tell a mega rare from a common one: three Tumeken's shadows and three
 * Lightbearers are both "three purples", though the shadow is five times rarer. So each drop is
 * weighted by its rarity, and the score is where the weighted total falls among the totals the same
 * kill counts would usually produce. Counting every drop as 1 is the same calculation with every
 * weight set to 1, which is what this replaces.
 *
 * <p>Each drop is worth one over the root of its expectation, which makes a source's total the sum
 * of its items' standardised deviations. Weighting by the full rate instead, so that a drop is
 * worth one over its chance, tracks rarity harder but hands a source over to its pet: at a thousand
 * Zulrah kills a mutagen would be worth more than four extra uniques, and an account running half
 * again over rate on uniques would still read average. Rooting it keeps a rare find worth several
 * common ones while the plain count still moves the verdict.
 *
 * <p>The weighted total is a sum of differently scaled Poissons, which is skewed enough that a
 * normal approximation is worst in the tails where the interesting verdicts are, so the
 * distribution is simulated instead. The seed is fixed and results are cached, so a source's score
 * never drifts between panel refreshes.
 */
final class RarityLuck
{
	private static final int TRIALS = 50_000;
	private static final long SEED = 7_459_221L;

	/** Above this a per-draw loop costs more than it is worth, and the normal fit is already good. */
	private static final double KNUTH_LIMIT = 30.0;

	private static final Map<String, Double> CACHE = new ConcurrentHashMap<>();

	private RarityLuck()
	{
	}

	/**
	 * @param expected  what each item's kill count should have produced
	 * @param collected how many of each the log actually shows
	 * @return the share of accounts at the same kill counts this one is luckier than
	 */
	static double percentile(double[] expected, int[] collected)
	{
		if (expected.length == 0)
		{
			return 0.5;
		}

		return CACHE.computeIfAbsent(key(expected, collected), k -> simulate(expected, collected));
	}

	/**
	 * What one of an item is worth, against one of something expected as often. The score and the
	 * ratio both read from here, so the two cannot drift into disagreeing about what a drop is worth.
	 */
	static double weight(double expected)
	{
		return expected > 0 ? 1.0 / Math.sqrt(expected) : 0;
	}

	/** What the account holds, in the same units. */
	static double weighted(double[] expected, int[] collected)
	{
		double total = 0;

		for (int i = 0; i < expected.length; i++)
		{
			total += collected[i] * weight(expected[i]);
		}

		return total;
	}

	/** What those kill counts should have produced, in the same units. */
	static double weightedExpectation(double[] expected)
	{
		double total = 0;

		for (double lambda : expected)
		{
			total += lambda * weight(lambda);
		}

		return total;
	}

	private static double simulate(double[] expected, int[] collected)
	{
		// A rarer item is worth more. The kill count is a shared factor between one over the chance
		// and one over the expectation, and a shared factor cancels out of a percentile.
		double[] weights = new double[expected.length];
		double target = 0;

		for (int i = 0; i < expected.length; i++)
		{
			if (expected[i] > 0)
			{
				weights[i] = weight(expected[i]);
				target += collected[i] * weights[i];
			}
		}

		Random random = new Random(SEED);
		double tolerance = 1.0e-9 * Math.max(1.0, target);
		int below = 0;
		int level = 0;

		for (int trial = 0; trial < TRIALS; trial++)
		{
			double total = 0;

			for (int i = 0; i < expected.length; i++)
			{
				if (expected[i] > 0)
				{
					total += poisson(random, expected[i]) * weights[i];
				}
			}

			if (total < target - tolerance)
			{
				below++;
			}
			else if (total <= target + tolerance)
			{
				level++;
			}
		}

		// Half credit for a tie, so a source nobody has touched sits at the middle rather than the
		// bottom, the same convention the counting version used.
		return (below + 0.5 * level) / TRIALS;
	}

	private static int poisson(Random random, double lambda)
	{
		if (lambda > KNUTH_LIMIT)
		{
			return Math.max(0, (int) Math.round(lambda + Math.sqrt(lambda) * random.nextGaussian()));
		}

		double limit = Math.exp(-lambda);
		double product = random.nextDouble();
		int count = 0;

		while (product > limit)
		{
			count++;
			product *= random.nextDouble();
		}

		return count;
	}

	private static String key(double[] expected, int[] collected)
	{
		StringBuilder key = new StringBuilder(expected.length * 16);

		for (int i = 0; i < expected.length; i++)
		{
			// Rounded, so a redraw that recomputes the same expectation reuses the cached answer.
			key.append(Math.round(expected[i] * 1.0e6)).append(':').append(collected[i]).append(';');
		}

		return key.toString();
	}
}

package com.spoonmeter;

import java.util.Comparator;

public enum SortMode
{
	CURSED_FIRST("Cursed first", Comparator.comparingDouble(SpoonReport.SourceLine::getPercentile)),
	SPOONED_FIRST("Spooned first", Comparator.comparingDouble(SpoonReport.SourceLine::getPercentile).reversed()),
	KC("Highest KC", Comparator.comparingInt(SpoonReport.SourceLine::getKc).reversed()),
	NAME("Name", Comparator.comparing(SpoonReport.SourceLine::getName, String.CASE_INSENSITIVE_ORDER));

	private final String label;
	private final Comparator<SpoonReport.SourceLine> comparator;

	SortMode(String label, Comparator<SpoonReport.SourceLine> comparator)
	{
		this.label = label;
		this.comparator = comparator;
	}

	public Comparator<SpoonReport.SourceLine> getComparator()
	{
		return comparator;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.spoonmeter;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;

/**
 * One boss/raid in the list. Click it to see which item is doing the bullying.
 *
 * <p>Every row puts its long text in {@code BorderLayout.CENTER} and its short value in
 * {@code EAST}. The sidebar is a fixed 225px, and a long name in {@code WEST} keeps its full
 * preferred width and overlaps the value; in {@code CENTER} it gets whatever is left over and
 * ellipsises. The full text is always on the tooltip.
 */
class SourceRow extends JPanel
{
	private static final Color DRY_TEXT = new Color(0xE0A030);
	private static final Color VERY_DRY_TEXT = new Color(0xE05A45);

	private final JPanel details;
	private boolean expanded;

	/** Held, because the item rows are built after the constructor has returned. */
	private final Consumer<String> onToggleItem;

	SourceRow(SpoonReport.SourceLine line, Consumer<String> onHide, Consumer<String> onToggleItem)
	{
		this.onToggleItem = onToggleItem;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(new EmptyBorder(6, 8, 6, 8));

		JPanel summary = new JPanel(new DynamicGridLayout(0, 1, 0, 3));
		summary.setOpaque(false);

		JPanel titleRow = new JPanel(new BorderLayout(4, 0));
		titleRow.setOpaque(false);

		JLabel name = new JLabel(line.getName() + (line.isApproximate() ? " *" : ""));
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(Color.WHITE);

		JLabel verdict = new JLabel(line.getRating().getTitle());
		verdict.setFont(FontManager.getRunescapeSmallFont());
		verdict.setForeground(line.getRating().getColor());

		titleRow.add(name, BorderLayout.CENTER);
		titleRow.add(verdict, BorderLayout.EAST);

		LuckBar bar = new LuckBar(6);
		bar.setPercentile(line.getPercentile());

		JPanel statsRow = new JPanel(new BorderLayout(4, 0));
		statsRow.setOpaque(false);

		// Just "1,498 kc" - the real counter names ("Corrupted Gauntlet completion count") are far
		// too long for the sidebar, so they live on the tooltip instead.
		JLabel kc = new JLabel(SpoonSummary.WHOLE.format(line.getKc()) + " kc" + scaling(line));
		kc.setFont(FontManager.getRunescapeSmallFont());
		kc.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		if (line.isScaled())
		{
			// Without this the figures look broken rather than misconfigured: a soloer left on the
			// default mass share sees twenty times the drops they should, with nothing on the row to
			// say the expectation rests on a setting at all.
			kc.setToolTipText("<html>These kills were counted as "
				+ SpoonSummary.ONE_DP.format(line.getRollsPerKc()) + " rolls each.<br>"
				+ "Change it in the plugin's settings if that is not how you fight it.</html>");
		}

		JLabel ratio = new JLabel(line.getObtained() + " / " + SpoonSummary.ONE_DP.format(line.getExpected())
			+ "  (" + SpoonSummary.ONE_DP.format(line.getRatio()) + "x)");
		ratio.setFont(FontManager.getRunescapeSmallFont());
		ratio.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		// The counts are there to be checked against the log, but the figure beside them weighs each
		// drop by how rare it is, so the two do not divide into one another where what you found was
		// unusually good or unusually cheap. That is the whole point of it, and it needs saying.
		ratio.setToolTipText("<html>" + line.getObtained() + " found against "
			+ SpoonSummary.ONE_DP.format(line.getExpected()) + " expected, which is "
			+ SpoonSummary.ONE_DP.format(line.getCountRatio()) + "x by count.<br>"
			+ "The " + SpoonSummary.ONE_DP.format(line.getRatio())
			+ "x weighs each drop by how rare it is, so a mega rare counts for more than a<br>"
			+ "common one. Two cheap drops and two expensive ones are not the same luck.</html>");

		statsRow.add(kc, BorderLayout.WEST);
		statsRow.add(ratio, BorderLayout.EAST);

		summary.add(titleRow);
		summary.add(bar);
		summary.add(statsRow);

		details = buildDetails(line);
		details.setVisible(false);

		add(summary, BorderLayout.NORTH);
		add(details, BorderLayout.CENTER);

		setToolTipText(buildTooltip(line));

		// Right-click to drop a boss you do not care about out of the list and the total.
		JPopupMenu menu = new JPopupMenu();
		JMenuItem hide = new JMenuItem("Hide " + line.getName());
		hide.addActionListener(e -> onHide.accept(line.getName()));
		menu.add(hide);
		setComponentPopupMenu(menu);

		// Children do not inherit a popup menu by default, so without this a right-click that
		// happens to land on a label inside the row would do nothing at all.
		inheritPopup(this);

		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				// Right-click belongs to the hide menu; only the left button expands the row.
				if (!SwingUtilities.isLeftMouseButton(e))
				{
					return;
				}

				expanded = !expanded;
				details.setVisible(expanded);
				revalidate();
				repaint();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		});
	}

	/**
	 * How much a kill was worth, where that is not one roll. A damage share reads as a percentage
	 * because that is how it is set; anything rolled repeatedly reads as a multiplier.
	 */
	private static String scaling(SpoonReport.SourceLine line)
	{
		if (!line.isScaled())
		{
			return "";
		}

		double rolls = line.getRollsPerKc();

		if (rolls < 1)
		{
			return "  · " + SpoonSummary.WHOLE.format(Math.round(rolls * 100)) + "% share";
		}

		return "  · x" + SpoonSummary.ONE_DP.format(rolls);
	}

	private static String buildTooltip(SpoonReport.SourceLine line)
	{
		StringBuilder tip = new StringBuilder("<html>").append(line.getName());

		for (Map.Entry<String, Integer> counter : line.getCounters().entrySet())
		{
			tip.append("<br>").append(counter.getKey()).append(": ")
				.append(SpoonSummary.WHOLE.format(counter.getValue()));
		}

		tip.append("<br>").append(line.getObtained()).append(" uniques vs ")
			.append(SpoonSummary.ONE_DP.format(line.getExpected())).append(" expected")
			.append("<br>Luckier than ").append(LuckRating.spoonScore(line.getPercentile()))
			.append("% of accounts");

		if (line.isApproximate())
		{
			tip.append("<br>* rates vary with team size / points");
		}

		return tip.append("<br>Click for the item breakdown</html>").toString();
	}

	private JPanel buildDetails(SpoonReport.SourceLine line)
	{
		JPanel panel = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
		panel.setOpaque(false);
		panel.setBorder(BorderFactory.createCompoundBorder(
			new EmptyBorder(6, 0, 0, 0),
			BorderFactory.createMatteBorder(1, 0, 0, 0, ColorScheme.MEDIUM_GRAY_COLOR)));

		for (SpoonReport.ItemLine item : line.getItems())
		{
			JPanel row = new JPanel(new BorderLayout(4, 0));
			row.setOpaque(false);
			row.setBorder(new EmptyBorder(3, 0, 0, 0));

			JLabel name = new JLabel(item.getName());
			name.setFont(FontManager.getRunescapeSmallFont());

			String right;
			Color colour;

			if (!item.isCounted())
			{
				// Shown but not scored, so the player can see what it holds and decide.
				name.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
				right = "not counted";
				colour = ColorScheme.MEDIUM_GRAY_COLOR;
			}
			else if (item.getObtained() > 0)
			{
				name.setForeground(Color.WHITE);
				right = item.getObtained() + " / " + SpoonSummary.ONE_DP.format(item.getExpected());
				colour = ColorScheme.LIGHT_GRAY_COLOR;
			}
			else
			{
				name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				long percent = Math.round(item.getDryness() * 100);
				right = percent + "% have it";
				colour = item.getDryness() >= 0.95 ? VERY_DRY_TEXT
					: item.getDryness() >= 0.75 ? DRY_TEXT : ColorScheme.LIGHT_GRAY_COLOR;
			}

			JLabel value = new JLabel(right);
			value.setFont(FontManager.getRunescapeSmallFont());
			value.setForeground(colour);

			StringBuilder tip = new StringBuilder("<html>").append(item.getName())
				.append("<br>1 in ")
				.append(SpoonSummary.WHOLE.format(Math.round(1.0 / item.getChance())))
				.append(" per attempt<br>")
				.append(SpoonSummary.ONE_DP.format(item.getExpected())).append(" expected, ")
				.append(item.getObtained()).append(" obtained");

			if (item.isUncountable())
			{
				tip.append("<br><br>This also drops somewhere the collection log never counts, so")
					.append("<br>the number here is not evidence about this source. Right-click")
					.append("<br>to count it anyway.");
			}
			else if (!item.isCounted())
			{
				tip.append("<br><br>You have turned this one off. Right-click to count it again.");
			}

			row.setToolTipText(tip.append("</html>").toString());

			JPopupMenu itemMenu = new JPopupMenu();
			JMenuItem toggle = new JMenuItem(
				item.isCounted() ? "Don't count " + item.getName() : "Count " + item.getName());
			toggle.addActionListener(e -> onToggleItem.accept(item.getName()));
			itemMenu.add(toggle);
			row.setComponentPopupMenu(itemMenu);
			name.setInheritsPopupMenu(true);
			value.setInheritsPopupMenu(true);

			row.add(name, BorderLayout.CENTER);
			row.add(value, BorderLayout.EAST);
			panel.add(row);
		}

		return panel;
	}

	/** Lets the row's popup menu answer a right-click anywhere inside it. */
	private static void inheritPopup(JComponent parent)
	{
		for (Component child : parent.getComponents())
		{
			if (child instanceof JComponent)
			{
				JComponent component = (JComponent) child;
				component.setInheritsPopupMenu(true);
				inheritPopup(component);
			}
		}
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}
}

