@PluginDescriptor(
	name = "Spoon Meter",
	description = "Rates how spooned or cursed your account is from collection log KC and uniques",
	tags = {"collection", "log", "luck", "drop", "rate", "spoon", "dry", "rng"},
	internalName = "spoon-meter"
)
public class SpoonMeterPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(SpoonMeterPlugin.class);

	private static final String COMMAND = "spoon";
	private static final String PUBLIC_COMMAND = "!spoon";
	private static final int SAVE_INTERVAL_TICKS = 50; // ~30 seconds

	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ChatCommandManager chatCommandManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Gson gson;

	@Inject
	private SpoonMeterConfig config;

	private final Map<String, CollectionLogPage> pages = new LinkedHashMap<>();

	private CollectionLogParser parser;
	private DropTable dropTable;
	private SpoonMeterPanel panel;
	private NavigationButton navButton;

	private boolean dirty;
	private boolean commandRegistered;
	private int ticksSinceSave;
	private Filepath dataDir;
	private String loadedProfileKey;
	private String lastFingerprint;

	@Provides
	SpoonMeterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SpoonMeterConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		parser = new CollectionLogParser(itemManager);

		dataDir = getPluginDirectory();
		dataDir.createDirectories();
		dropTable = DropTable.load(gson, dataDir.joinSegment("drop_rates.json"));

		panel = new SpoonMeterPanel(this);

		BufferedImage icon = ImageUtil.loadImageResource(SpoonMeterPlugin.class, "/com/spoonmeter/icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Spoon Meter")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		setChatCommandRegistered(config.publicChatCommand());

		loadForCurrentProfile();
		refreshPanel();

		log.info("Spoon Meter started: sidebar button added, {} drop sources, {} saved pages",
			dropTable.getSources().size(), pages.size());
	}

	@Override
	protected void shutDown() throws Exception
	{
		flush(false);
		setChatCommandRegistered(false);
		clientToolbar.removeNavigation(navButton);
		pages.clear();
		panel = null;
		navButton = null;
		lastFingerprint = null;
		loadedProfileKey = null;
		dataDir = null;
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		loadForCurrentProfile();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			loadForCurrentProfile();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			flush();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == CollectionLogParser.COLLECTION_LOG_GROUP_ID)
		{
			lastFingerprint = null;
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == CollectionLogParser.COLLECTION_LOG_GROUP_ID)
		{
			lastFingerprint = null;
			flush();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		// Checked every tick rather than tracked with a flag: enabling the plugin while the log is
		// already open still works, and a missed close event cannot wedge it.
		if (parser.isLogOpen(client))
		{
			readOpenPage();
		}

		if (dirty && ++ticksSinceSave >= SAVE_INTERVAL_TICKS)
		{
			flush();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (SpoonMeterConfig.GROUP.equals(event.getGroup()))
		{
			setChatCommandRegistered(config.publicChatCommand());
			refreshPanel();
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		if (!config.chatCommand() || !COMMAND.equalsIgnoreCase(event.getCommand()))
		{
			return;
		}

		SpoonReport report = buildReport();

		String message = report.isEmpty()
			? new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append("Spoon Meter: ")
				.append(ChatColorType.NORMAL).append("no rated pages yet - open your collection log.")
				.build()
			: new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append("Spoon Meter: ")
				.append(ChatColorType.NORMAL).append(SpoonSummary.oneLine(report))
				.build();

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	/**
	 * Handles {@code !spoon} typed into public, clan or friends chat.
	 *
	 * <p>This rewrites the message where it is displayed, exactly like {@code !kc} does. Everyone
	 * else still receives the literal "!spoon" text: the client cannot alter what is sent, and
	 * nobody else's client holds this account's collection log to look the answer up with.
	 */
	private void onSpoonChatCommand(ChatMessage chatMessage, String message)
	{
		Player local = client.getLocalPlayer();

		// Someone else's !spoon must be left alone rather than answered with our numbers.
		if (local == null || local.getName() == null
			|| !local.getName().equals(Text.sanitize(chatMessage.getName())))
		{
			return;
		}

		SpoonReport report = buildReport();
		String argument = message.length() > PUBLIC_COMMAND.length()
			? message.substring(PUBLIC_COMMAND.length()) : "";

		String line = report.isEmpty()
			? "Spoon Meter: no rated pages yet"
			: SpoonSummary.chatLine(report, argument);

		MessageNode node = chatMessage.getMessageNode();
		node.setRuneLiteFormatMessage(new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append(line)
			.build());

		client.refreshChat();
	}

	private void setChatCommandRegistered(boolean wanted)
	{
		if (wanted == commandRegistered)
		{
			return;
		}

		if (wanted)
		{
			chatCommandManager.registerCommand(PUBLIC_COMMAND, this::onSpoonChatCommand);
		}
		else
		{
			chatCommandManager.unregisterCommand(PUBLIC_COMMAND);
		}

		commandRegistered = wanted;
	}

	/** Names the user has hidden, normalised so the stored spelling does not have to be exact. */
	private Set<String> hiddenSources()
	{
		Set<String> hidden = new HashSet<>();

		for (String name : Text.fromCSV(config.hiddenSources()))
		{
			hidden.add(DropTable.normalise(name));
		}

		return hidden;
	}

	/** Called by the panel when a boss is hidden from its right-click menu. */
	void hideSource(String name)
	{
		List<String> names = new ArrayList<>(Text.fromCSV(config.hiddenSources()));

		if (names.stream().noneMatch(existing -> DropTable.normalise(existing).equals(DropTable.normalise(name))))
		{
			names.add(name);
			configManager.setConfiguration(SpoonMeterConfig.GROUP, "hiddenSources", Text.toCSV(names));
		}
	}

	/** Items the user has turned on or off from an item's right-click menu. */
	private Set<String> flippedItems()
	{
		Set<String> flipped = new HashSet<>();

		for (String name : Text.fromCSV(config.flippedItems()))
		{
			flipped.add(DropTable.normalise(name));
		}

		return flipped;
	}

	/**
	 * Called by the panel when an item's counting is turned around. An occult necklace also drops
	 * off ordinary smoke devils, so it is not scored by default; a player who knows their own came
	 * off the boss can say so, and anyone can silence an ordinary item the same way.
	 */
	void toggleItem(String name)
	{
		List<String> names = new ArrayList<>(Text.fromCSV(config.flippedItems()));
		String wanted = DropTable.normalise(name);

		if (!names.removeIf(existing -> DropTable.normalise(existing).equals(wanted)))
		{
			names.add(name);
		}

		configManager.setConfiguration(SpoonMeterConfig.GROUP, "flippedItems", Text.toCSV(names));
	}

	/** Called by the panel's footer when the user wants them all back. */
	void clearHiddenSources()
	{
		configManager.setConfiguration(SpoonMeterConfig.GROUP, "hiddenSources", "");
	}

	int hiddenCount()
	{
		return hiddenSources().size();
	}

	/** Called by the panel when the user picks a different sort order. */
	void setSortMode(SortMode sortMode)
	{
		if (sortMode != null && sortMode != config.sortMode())
		{
			configManager.setConfiguration(SpoonMeterConfig.GROUP, "sortMode", sortMode);
		}
	}

	private void readOpenPage()
	{
		CollectionLogPage page = parser.parseOpenPage(client);

		if (page == null)
		{
			return;
		}

		String fingerprint = page.fingerprint();

		if (fingerprint.equals(lastFingerprint))
		{
			return;
		}

		lastFingerprint = fingerprint;

		CollectionLogPage previous = pages.put(page.getName(), page);

		if (previous == null || !previous.fingerprint().equals(fingerprint))
		{
			dirty = true;
			refreshPanel();
		}
	}

	private SpoonReport buildReport()
	{
		Map<String, Double> uniqueChances = new HashMap<>();
		uniqueChances.put("cox", config.coxUniqueChance() / 100.0);
		uniqueChances.put("coxcm", config.coxCmUniqueChance() / 100.0);
		uniqueChances.put("tob", config.tobUniqueChance() / 100.0);
		uniqueChances.put("tobhm", config.tobHardUniqueChance() / 100.0);
		uniqueChances.put("toa", config.toaUniqueChance() / 100.0);
		uniqueChances.put("toaexpert", config.toaExpertUniqueChance() / 100.0);
		uniqueChances.put("doom", config.doomUniqueChance() / 100.0);
		uniqueChances.put("tfa", config.tfaUniqueChance() / 100.0);

		// Not a chance but a roll count, and it shares the map because both are numbers the player
		// has to supply for a source whose rate the log cannot pin down on its own.
		// Not a chance but a share of one roll: the Hueycoatl's unique chance is per player and
		// divided by damage, so a mass world is a fraction of a solo's roll.
		uniqueChances.put("hueycontribution", config.hueycoatlContribution() / 100.0);

		// Awakened rolls the unique table three times as often, so a mix of the two is worth
		// somewhere between one roll and three. Derived here rather than stored, so that fighting
		// none of them awakened reads as a normal kill instead of leaving the bosses unrated.
		uniqueChances.put("dt2awakened", 1.0 + 2.0 * (config.dt2AwakenedShare() / 100.0));

		return SpoonReport.build(pages.values(), dropTable, uniqueChances, config.minimumKc(),
			config.hideCombinedPages(), hiddenSources(), flippedItems());
	}

	private void refreshPanel()
	{
		if (panel == null)
		{
			return;
		}

		SpoonReport report = buildReport();
		SortMode sortMode = config.sortMode();
		SwingUtilities.invokeLater(() -> panel.update(report, sortMode));
	}

	// --- persistence ----------------------------------------------------------------------
	// Kept as a file rather than in the config service: a full collection log is far too big to be
	// sensible as a synced config value, and it is per account anyway. All of it goes through
	// Filepath, which confines the plugin to its own directory under ~/.runelite/plugin-data.

	private Filepath dataFile(String profileKey)
	{
		// Filepath rejects anything that could escape the directory, but a profile key is not meant to
		// carry punctuation in the first place, so it is flattened before it gets there.
		return dataDir.joinSegment(profileKey.replaceAll("[^A-Za-z0-9_.-]", "_") + ".json");
	}

	/**
	 * RuneLite's RS profile key identifies the logged in account without exposing anything about it,
	 * and changes when you switch accounts, which is exactly when the saved log should switch too.
	 */
	private void loadForCurrentProfile()
	{
		String profileKey = configManager.getRSProfileKey();

		if (profileKey == null || profileKey.equals(loadedProfileKey) || dataDir == null)
		{
			return;
		}

		flush();

		loadedProfileKey = profileKey;
		pages.clear();
		lastFingerprint = null;

		Filepath file = dataFile(profileKey);

		if (file.isFile())
		{
			Type type = new TypeToken<Map<String, CollectionLogPage>>()
			{
			}.getType();

			try (Reader reader = file.openBufferedReader())
			{
				Map<String, CollectionLogPage> saved = gson.fromJson(reader, type);

				if (saved != null)
				{
					pages.putAll(saved);
					dropStalePersonalBests();
				}
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Could not read saved collection log data from {}", file, e);
			}
		}

		refreshPanel();
	}

	/**
	 * Earlier builds read "Personal Best: 9:51" as a counter called "Personal Best: 9" worth 51,
	 * which outranks the real kill count on any page with fewer kills than that. The parser no
	 * longer produces them, but saved files still hold them until each page is opened again.
	 */
	private void dropStalePersonalBests()
	{
		int removed = 0;

		for (CollectionLogPage page : pages.values())
		{
			removed += page.getCounters().keySet()
				.removeIf(label -> label.toLowerCase(Locale.ENGLISH).startsWith("personal best")) ? 1 : 0;
		}

		if (removed > 0)
		{
			dirty = true;
			log.info("Dropped personal best times from {} saved pages", removed);
		}
	}

	/** Writes pending changes off the client thread. */
	private void flush()
	{
		flush(true);
	}

	private void flush(boolean async)
	{
		ticksSinceSave = 0;

		if (!dirty || loadedProfileKey == null || dataDir == null || pages.isEmpty())
		{
			return;
		}

		dirty = false;

		Map<String, CollectionLogPage> snapshot = new LinkedHashMap<>(pages);
		Filepath file = dataFile(loadedProfileKey);

		if (async)
		{
			executor.execute(() -> write(file, snapshot));
		}
		else
		{
			// On shutdown there may be no executor left to run it later.
			write(file, snapshot);
		}
	}

	private void write(Filepath file, Map<String, CollectionLogPage> snapshot)
	{
		try (Writer writer = file.openBufferedWriter())
		{
			gson.toJson(snapshot, writer);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not save collection log data to {}", file, e);
		}
	}
}

package com.spoonmeter;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;

/**
 * The rating itself: every collection log page we have data and rates for, scored against how many
 * uniques the KC should have produced, plus the aggregate verdict for the account.
 */
public class SpoonReport
{
	/** One unique on a page: what it should have cost, and what it actually cost. */
	public static class ItemLine
	{
		private final String name;
		private final double chance;
		private final int obtained;
		private final double expected;
		private final double dryness;

		/** Whether this item is being scored, or only listed. */
		private final boolean counted;

		/** Whether it is the kind of item the collection log cannot count honestly. */
		private final boolean uncountable;

		ItemLine(String name, double chance, int obtained, double expected, double dryness,
			boolean counted, boolean uncountable)
		{
			this.name = name;
			this.chance = chance;
			this.obtained = obtained;
			this.expected = expected;
			this.dryness = dryness;
			this.counted = counted;
			this.uncountable = uncountable;
		}

		public boolean isCounted()
		{
			return counted;
		}

		public boolean isUncountable()
		{
			return uncountable;
		}

		public String getName()
		{
			return name;
		}

		/**
		 * Effective chance per attempt. On a page whose attempts are split across variants at
		 * different rates - normal and corrupted Gauntlet, say - this is the blend, so it moves as
		 * the split does.
		 */
		public double getChance()
		{
			return chance;
		}

		public int getObtained()
		{
			return obtained;
		}

		public double getExpected()
		{
			return expected;
		}

		/**
		 * Share of players who would already own this item after the same attempts. Only meaningful
		 * while you do not: 0.97 means 97 in 100 have it and you do not.
		 */
		public double getDryness()
		{
			return dryness;
		}
	}

	public static class SourceLine
	{
		private final String name;
		private final Map<String, Integer> counters;
		private final int kc;
		private final int obtained;
		private final double expected;
		private final double percentile;
		private final LuckRating rating;
		private final boolean approximate;

		/** Rolls per counted kill: below one where the roll is shared out, above one where repeated. */
		private final double rollsPerKc;

		/** The same totals as {@link #obtained} and {@link #expected}, weighted by how rare each is. */
		private final double weighted;
		private final double weightedExpected;
		private final List<ItemLine> items;

		SourceLine(String name, Map<String, Integer> counters, int kc, int obtained, double expected,
			double percentile, boolean approximate, double rollsPerKc, double weighted,
			double weightedExpected, List<ItemLine> items)
		{
			this.name = name;
			this.counters = counters;
			this.kc = kc;
			this.obtained = obtained;
			this.expected = expected;
			this.percentile = percentile;
			this.rating = LuckRating.fromPercentile(percentile);
			this.approximate = approximate;
			this.rollsPerKc = rollsPerKc;
			this.weighted = weighted;
			this.weightedExpected = weightedExpected;
			this.items = items;
		}

		public String getName()
		{
			return name;
		}

		/** The counters that actually fed the rating, in table order. */
		public Map<String, Integer> getCounters()
		{
			return counters;
		}

		/** Total attempts across every counted variant. */
		public int getKc()
		{
			return kc;
		}

		public int getObtained()
		{
			return obtained;
		}

		public double getExpected()
		{
			return expected;
		}

		public double getPercentile()
		{
			return percentile;
		}

		public LuckRating getRating()
		{
			return rating;
		}

		public double getRollsPerKc()
		{
			return rollsPerKc;
		}

		/** Whether the kill count alone does not say how many rolls the account actually got. */
		public boolean isScaled()
		{
			return Math.abs(rollsPerKc - 1.0) > 1.0e-9;
		}

		public boolean isApproximate()
		{
			return approximate;
		}

		public List<ItemLine> getItems()
		{
			return items;
		}

		/** Uniques per expected unique, counting every drop the same. 2.0 is double rate. */
		public double getCountRatio()
		{
			return expected <= 0 ? 1.0 : obtained / expected;
		}

		/**
		 * The same thing with each drop worth what its rarity makes it worth, which is what the
		 * panel shows. A plain count cannot separate two mega rares from two common ones and reads
		 * identically for both, which is the complaint this answers.
		 */
		public double getRatio()
		{
			return weightedExpected <= 0 ? 1.0 : weighted / weightedExpected;
		}

		/** The item you are furthest behind on, or null if nothing notable is missing. */
		public ItemLine getDriestMissing()
		{
			ItemLine driest = null;

			for (ItemLine item : items)
			{
				if (item.getObtained() == 0 && (driest == null || item.getDryness() > driest.getDryness()))
				{
					driest = item;
				}
			}

			return driest != null && driest.getDryness() >= 0.5 ? driest : null;
		}
	}

	/** Running totals for one item while its variants are being added up. */
	private static final class Accumulator
	{
		private final String name;
		private boolean counted = true;
		private boolean uncountable;
		private double expected;
		private double missProbability = 1.0;

		/** What the page displays, which for a shared item is the account-wide total. */
		private int shown;

		/** This page's share of {@link #shown} once the item has been pooled. */
		private int allocated;
		private double remainder;

		private Accumulator(String name)
		{
			this.name = name;
		}
	}

	/** One page's expectations, before shared items have been divided up. */
	private static final class Scored
	{
		private final String name;
		private final Map<String, Integer> counters;
		private final int kc;
		private final boolean approximate;
		private final double rollsPerKc;
		private final Map<String, Accumulator> items;

		private Scored(String name, Map<String, Integer> counters, int kc, boolean approximate,
			double rollsPerKc, Map<String, Accumulator> items)
		{
			this.name = name;
			this.counters = counters;
			this.kc = kc;
			this.approximate = approximate;
			this.rollsPerKc = rollsPerKc;
			this.items = items;
		}
	}

	private final List<SourceLine> sources;
	private final int obtained;
	private final double expected;
	private final double percentile;
	private final LuckRating rating;
	private final int pagesSeen;

	/** The account's totals with each drop worth what its rarity makes it worth. */
	private final double weighted;
	private final double weightedExpected;

	private SpoonReport(List<SourceLine> sources, int obtained, double expected, double percentile,
		double weighted, double weightedExpected, int pagesSeen)
	{
		this.sources = sources;
		this.obtained = obtained;
		this.expected = expected;
		this.percentile = percentile;
		this.rating = LuckRating.fromPercentile(percentile);
		this.weighted = weighted;
		this.weightedExpected = weightedExpected;
		this.pagesSeen = pagesSeen;
	}

	public List<SourceLine> getSources()
	{
		return Collections.unmodifiableList(sources);
	}

	public int getObtained()
	{
		return obtained;
	}

	public double getExpected()
	{
		return expected;
	}

	public double getPercentile()
	{
		return percentile;
	}

	public LuckRating getRating()
	{
		return rating;
	}

	public int getSpoonScore()
	{
		return LuckRating.spoonScore(percentile);
	}

	/** Pages we have data for, including ones with no drop rates or too little KC to rate. */
	public int getPagesSeen()
	{
		return pagesSeen;
	}

	public boolean isEmpty()
	{
		return sources.isEmpty();
	}

	/** Uniques per expected unique, counting every drop the same. */
	public double getCountRatio()
	{
		return expected <= 0 ? 1.0 : obtained / expected;
	}

	/** The same, weighted by rarity, so it agrees with the score and with each source's own ratio. */
	public double getRatio()
	{
		return weightedExpected <= 0 ? 1.0 : weighted / weightedExpected;
	}

	/**
	 * Scores every page we can, then rolls them into one account-wide verdict.
	 *
	 * <p>Done in two passes because of shared items. A collection log page shows your <b>total</b>
	 * quantity of an item, not the amount that source gave you, so an item with several sources
	 * appears in full on each of their pages: one Virtus robe top reads as three across the
	 * Desert Treasure bosses, and one uncut onyx reads as three across Zulrah, Zalcano and Skotizo.
	 * Counting each page separately would multiply it by the number of sources.
	 *
	 * <p>So the first pass works out what each page expects, the second pools each item across its
	 * sources - expectations summed, the count taken once - and hands the count back out in
	 * proportion to how much of the expectation each page is responsible for. A page with one kill
	 * can no longer claim a drop that a page with 252 earned.
	 *
	 * @param uniqueChances per-completion unique chance for the weight-based raid entries, keyed by
	 *                      the variant's uniqueChanceKey
	 * @param minKc         pages below this many attempts are ignored; a handful says nothing
	 */
	public static SpoonReport build(Collection<CollectionLogPage> pages, DropTable dropTable,
		Map<String, Double> uniqueChances, int minKc)
	{
		return build(pages, dropTable, uniqueChances, minKc, false, Collections.emptySet(),
			Collections.emptySet());
	}

	public static SpoonReport build(Collection<CollectionLogPage> pages, DropTable dropTable,
		Map<String, Double> uniqueChances, int minKc, boolean hideCombined)
	{
		return build(pages, dropTable, uniqueChances, minKc, hideCombined, Collections.emptySet(),
			Collections.emptySet());
	}

	/**
	 * @param hideCombined leave out pages that cover several different bosses at once, where a
	 *                     single verdict says little about any one of them
	 */
	public static SpoonReport build(Collection<CollectionLogPage> pages, DropTable dropTable,
		Map<String, Double> uniqueChances, int minKc, boolean hideCombined, Set<String> hidden)
	{
		return build(pages, dropTable, uniqueChances, minKc, hideCombined, hidden,
			Collections.emptySet());
	}

	/**
	 * @param flippedItems items whose counting has been turned around from its default, so that one
	 *                     the log cannot count honestly is scored anyway, or an ordinary one is not
	 */
	public static SpoonReport build(Collection<CollectionLogPage> pages, DropTable dropTable,
		Map<String, Double> uniqueChances, int minKc, boolean hideCombined, Set<String> hidden,
		Set<String> flippedItems)
	{
		List<Scored> scored = new ArrayList<>();

		for (CollectionLogPage page : pages)
		{
			Scored candidate = expectations(page, dropTable, uniqueChances, minKc, hideCombined,
				hidden, flippedItems);

			if (candidate != null)
			{
				scored.add(candidate);
			}
		}

		shareItems(scored);

		List<SourceLine> lines = new ArrayList<>();
		int totalObtained = 0;
		double totalExpected = 0;
		double totalWeighted = 0;
		double totalWeightedExpected = 0;

		for (Scored page : scored)
		{
			List<ItemLine> items = new ArrayList<>();
			int pageObtained = 0;
			double pageExpected = 0;

			// Kept item by item, because the score weighs a mega rare more heavily than a common
			// unique and a page total cannot tell them apart.
			double[] expectedPerItem = new double[page.items.size()];
			int[] collectedPerItem = new int[page.items.size()];
			int index = 0;

			for (Accumulator accumulator : page.items.values())
			{
				// An item that is only listed still shows its figures, so the player can see what
				// it would have been worth and decide, but it moves nothing.
				if (accumulator.counted)
				{
					pageObtained += accumulator.allocated;
					pageExpected += accumulator.expected;

					expectedPerItem[index] = accumulator.expected;
					collectedPerItem[index] = accumulator.allocated;
					index++;
				}

				items.add(new ItemLine(accumulator.name, accumulator.expected / page.kc,
					accumulator.allocated, accumulator.expected, 1.0 - accumulator.missProbability,
					accumulator.counted, accumulator.uncountable));
			}

			if (pageExpected <= 0)
			{
				continue;
			}

			totalObtained += pageObtained;
			totalExpected += pageExpected;

			if (index < expectedPerItem.length)
			{
				expectedPerItem = java.util.Arrays.copyOf(expectedPerItem, index);
				collectedPerItem = java.util.Arrays.copyOf(collectedPerItem, index);
			}

			double weighted = RarityLuck.weighted(expectedPerItem, collectedPerItem);
			double weightedExpected = RarityLuck.weightedExpectation(expectedPerItem);

			totalWeighted += weighted;
			totalWeightedExpected += weightedExpected;

			lines.add(new SourceLine(page.name, page.counters, page.kc, pageObtained, pageExpected,
				RarityLuck.percentile(expectedPerItem, collectedPerItem), page.approximate,
				page.rollsPerKc, weighted, weightedExpected, items));
		}

		return new SpoonReport(lines, totalObtained, totalExpected, accountPercentile(lines),
			totalWeighted, totalWeightedExpected, pages.size());
	}

	/**
	 * The account score is the average of the per-source scores, not one percentile over the pooled
	 * totals. Pooling sums every source into a single Poisson whose plausible band is proportionally
	 * tiny - at 400 expected drops, running 13% below rate already reads 0 out of 100 - so any
	 * shortfall that applies to every source at once, such as loot left on the floor or kills from
	 * before the log tracked them, pins the score to zero, and each further page tightens the band
	 * instead of loosening it. Averaging keeps each source's own band, which is wide enough for luck
	 * to dominate, and lets a spoon at a small boss lift the total the way players expect.
	 */
	private static double accountPercentile(List<SourceLine> lines)
	{
		if (lines.isEmpty())
		{
			return 0.5;
		}

		double sum = 0;

		for (SourceLine line : lines)
		{
			sum += line.getPercentile();
		}

		return sum / lines.size();
	}

	/** First pass: what this page's kill counts should have produced, and what the log shows. */
	@Nullable
	private static Scored expectations(CollectionLogPage page, DropTable dropTable,
		Map<String, Double> uniqueChances, int minKc, boolean hideCombined, Set<String> hidden,
		Set<String> flippedItems)
	{
		DropTable.Source source = dropTable.find(page.getName());

		if (source == null
			|| (hideCombined && source.isCombined())
			|| hidden.contains(DropTable.normalise(page.getName())))
		{
			return null;
		}

		Map<String, Accumulator> accumulated = new LinkedHashMap<>();
		Map<String, Integer> countersUsed = new LinkedHashMap<>();
		int totalKc = 0;

		// What a kill was worth, collected per item. Reported only when every item agrees, because
		// "each kill counted as N rolls" is a claim about the whole source.
		Set<Double> rollsSeen = new LinkedHashSet<>();

		for (DropTable.Variant variant : source.getVariants())
		{
			String counter = variant.getCounter();
			int kc = counter == null ? page.getPrimaryCount() : page.counterValue(counter);

			if (kc <= 0)
			{
				continue;
			}

			double uniqueChance = 0.0;

			if (variant.getUniqueChanceKey() != null)
			{
				Double configured = uniqueChances.get(variant.getUniqueChanceKey());

				if (configured == null || configured <= 0)
				{
					continue;
				}

				uniqueChance = configured;
			}

			// Most sources roll once per counted kill. A minigame can roll many times for one
			// counted completion, at a number only the player knows, so the rolls are scaled apart
			// from the kill count the panel shows.
			double rolls = kc;

			if (variant.getRollsPerKcKey() != null)
			{
				Double perKc = uniqueChances.get(variant.getRollsPerKcKey());

				if (perKc == null || perKc <= 0)
				{
					continue;
				}

				rolls = kc * perKc;
			}

			totalKc += kc;
			countersUsed.put(counter == null ? page.getPrimaryCounterLabel() : counter, kc);

			for (DropTable.Item item : variant.getItems())
			{
				double chance = DropTable.probability(variant, item, uniqueChance);

				if (chance <= 0)
				{
					continue;
				}

				// An item may be rolled more often than the rest of its source: an awakened Desert
				// Treasure boss rolls its unique table three times as often, while the orb and the
				// pet beside it are rolled outside that table and are left alone.
				//
				// A key on the variant says the source cannot be rated at all until the player
				// supplies it, as with the Hueycoatl's damage share. A key on one item only
				// modifies a rate that is already known, so leaving it unset means the ordinary
				// kill rather than an item nobody can score.
				double itemRolls = rolls;

				if (item.getRollsPerKcKey() != null)
				{
					Double perItem = uniqueChances.get(item.getRollsPerKcKey());

					if (perItem != null && perItem > 0)
					{
						itemRolls = kc * perItem;
					}
				}

				rollsSeen.add(itemRolls / kc);

				String key = DropTable.normalise(item.getName());
				Accumulator accumulator = accumulated.computeIfAbsent(key, k -> new Accumulator(item.getName()));

				// An item the log cannot count honestly is listed but not scored, unless the player
				// says their own copies did come from here. An ordinary one is scored unless they
				// say otherwise.
				accumulator.uncountable = item.isUncounted();
				accumulator.counted = item.isUncounted() == flippedItems.contains(key);

				accumulator.expected += itemRolls * chance;
				accumulator.missProbability *= Math.pow(1.0 - chance, itemRolls);
				accumulator.shown = page.quantityOfAny(item.getNames());
			}
		}

		if (totalKc < Math.max(1, minKc) || accumulated.isEmpty())
		{
			return null;
		}

		return new Scored(page.getName(), countersUsed, totalKc, source.isApprox(),
			rollsSeen.size() == 1 ? rollsSeen.iterator().next() : 1.0, accumulated);
	}

	/**
	 * Second pass: pool each item across the pages that can drop it, then hand the count back out
	 * by expectation share. Largest remainder keeps the parts whole and still summing to the total.
	 */
	private static void shareItems(List<Scored> scored)
	{
		Map<String, List<Accumulator>> byItem = new LinkedHashMap<>();

		for (Scored page : scored)
		{
			for (Map.Entry<String, Accumulator> entry : page.items.entrySet())
			{
				byItem.computeIfAbsent(entry.getKey(), k -> new ArrayList<>()).add(entry.getValue());
			}
		}

		for (List<Accumulator> sources : byItem.values())
		{
			if (sources.size() == 1)
			{
				Accumulator only = sources.get(0);
				only.allocated = only.shown;
				continue;
			}

			// Every page shows the same running total, so the largest is simply the freshest read.
			int owned = 0;
			double expected = 0;

			for (Accumulator source : sources)
			{
				owned = Math.max(owned, source.shown);
				expected += source.expected;
			}

			// The chance of owning one at all is a question about every source at once.
			double miss = 1.0;

			for (Accumulator source : sources)
			{
				miss *= source.missProbability;
			}

			int handedOut = 0;

			for (Accumulator source : sources)
			{
				source.missProbability = miss;

				double share = expected <= 0 ? 0 : owned * (source.expected / expected);
				source.allocated = (int) Math.floor(share);
				source.remainder = share - source.allocated;
				handedOut += source.allocated;
			}

			// Whatever rounding left over goes to the pages with the strongest claim.
			List<Accumulator> byRemainder = new ArrayList<>(sources);
			byRemainder.sort(Comparator.comparingDouble((Accumulator a) -> a.remainder).reversed());

			for (int i = 0; handedOut < owned && i < byRemainder.size(); i++, handedOut++)
			{
				byRemainder.get(i).allocated++;
			}
		}
	}
}

package com.spoonmeter;

import java.text.DecimalFormat;
import java.util.ArrayList;
import java.util.List;

/** Turns a report into text, for the clipboard button and the chat command. */
final class SpoonSummary
{
	static final DecimalFormat ONE_DP = new DecimalFormat("#,##0.0");
	static final DecimalFormat WHOLE = new DecimalFormat("#,##0");

	private SpoonSummary()
	{
	}

	/** "Cursed - 12/100 - 14 uniques vs 21.3 expected (0.66x)". */
	static String oneLine(SpoonReport report)
	{
		return report.getRating().getTitle()
			+ " - " + report.getSpoonScore() + "/100 - "
			+ WHOLE.format(report.getObtained()) + " uniques vs "
			+ ONE_DP.format(report.getExpected()) + " expected ("
			+ ONE_DP.format(report.getRatio()) + "x)";
	}

	/** The game's public/clan chat box refuses anything longer than this. */
	static final int MAX_CHAT_LENGTH = 80;

	/**
	 * A single line that fits in a game chat message. Detail is dropped in order of importance until
	 * it fits, so a long rating name plus large numbers degrades gracefully instead of being cut off
	 * mid-word.
	 *
	 * @param argument optional boss name; blank for the account-wide verdict
	 */
	static String chatLine(SpoonReport report, String argument)
	{
		String subject = "";
		LuckRating rating = report.getRating();
		int score = report.getSpoonScore();
		int obtained = report.getObtained();
		double expected = report.getExpected();
		double ratio = report.getRatio();

		// Only a single page has a kill count worth printing. Summing attempts across different
		// bosses would be a number that means nothing, so the account line goes without.
		int kc = 0;

		if (argument != null && !argument.trim().isEmpty())
		{
			SpoonReport.SourceLine match = findSource(report, argument);

			if (match == null)
			{
				return "Spoon Meter: no rated page matching " + argument.trim();
			}

			subject = " " + match.getName();
			rating = match.getRating();
			score = LuckRating.spoonScore(match.getPercentile());
			obtained = match.getObtained();
			expected = match.getExpected();
			ratio = match.getRatio();
			kc = match.getKc();
		}

		String head = "Spoon Meter" + subject + ": " + rating.getTitle() + " (" + score + "/100)";
		String lead = kc > 0 ? " - " + WHOLE.format(kc) + " kc," : " -";

		String[] candidates = {
			head + lead + " " + WHOLE.format(obtained) + " uniques vs " + ONE_DP.format(expected)
				+ " expected, " + ONE_DP.format(ratio) + "x",
			head + lead + " " + WHOLE.format(obtained) + " vs " + ONE_DP.format(expected)
				+ ", " + ONE_DP.format(ratio) + "x",
			head + lead + " " + ONE_DP.format(ratio) + "x",
			head + (kc > 0 ? " - " + WHOLE.format(kc) + " kc" : ""),
			head
		};

		for (String candidate : candidates)
		{
			if (candidate.length() <= MAX_CHAT_LENGTH)
			{
				return candidate;
			}
		}

		String shortest = candidates[candidates.length - 1];
		return shortest.length() <= MAX_CHAT_LENGTH ? shortest : shortest.substring(0, MAX_CHAT_LENGTH);
	}

	private static SpoonReport.SourceLine findSource(SpoonReport report, String argument)
	{
		String wanted = DropTable.normalise(argument);

		for (SpoonReport.SourceLine source : report.getSources())
		{
			if (DropTable.normalise(source.getName()).equals(wanted))
			{
				return source;
			}
		}

		for (SpoonReport.SourceLine source : report.getSources())
		{
			if (DropTable.normalise(source.getName()).contains(wanted))
			{
				return source;
			}
		}

		return null;
	}

	static String forClipboard(SpoonReport report, SortMode sortMode)
	{
		StringBuilder sb = new StringBuilder();
		sb.append("Spoon Meter\n");
		sb.append(oneLine(report)).append('\n');
		sb.append("Luckier than ").append(report.getSpoonScore())
			.append("% of accounts at the same KC.\n\n");

		List<SpoonReport.SourceLine> sources = new ArrayList<>(report.getSources());
		sources.sort(sortMode.getComparator());

		for (SpoonReport.SourceLine source : sources)
		{
			sb.append(source.getName())
				.append(" - ").append(WHOLE.format(source.getKc())).append(" kc - ")
				.append(source.getObtained()).append('/').append(ONE_DP.format(source.getExpected()))
				.append(" (").append(ONE_DP.format(source.getRatio())).append("x) - ")
				.append(source.getRating().getTitle());

			SpoonReport.ItemLine driest = source.getDriestMissing();

			if (driest != null)
			{
				sb.append(" - driest: ").append(driest.getName())
					.append(" (").append(Math.round(driest.getDryness() * 100)).append("% have it)");
			}

			sb.append('\n');
		}

		return sb.toString();
	}
}

package com.spoonmeter;

import com.google.gson.Gson;
import java.io.IOException;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class DropTableTest
{
	private DropTable dropTable;

	@Before
	public void setUp() throws IOException
	{
		dropTable = DropTable.load(new Gson(), null);
	}

	@Test
	public void loadsTheBundledTable()
	{
		assertTrue(dropTable.getSources().size() > 20);
		assertNotNull(dropTable.find("Zulrah"));
		assertNotNull(dropTable.find("Chambers of Xeric"));
		assertNull(dropTable.find("Some Boss That Does Not Exist"));
	}

	@Test
	public void lookupSurvivesPunctuationAndCase()
	{
		assertNotNull(dropTable.find("KREE'ARRA"));
		assertNotNull(dropTable.find("kreearra"));
		assertNotNull(dropTable.find("The Nightmare"));
		assertNotNull(dropTable.find("Nightmare"));
		assertEquals("sanguinesti staff", DropTable.normalise("Sanguinesti staff (uncharged)"));
	}

	@Test
	public void flatRatesAreInverted()
	{
		DropTable.Source zulrah = dropTable.find("Zulrah");
		assertEquals(1.0 / 512, probabilityOf(zulrah, "Tanzanite fang", 0), 1.0e-12);
		assertEquals(1.0 / 4000, probabilityOf(zulrah, "Pet snakeling", 0), 1.0e-12);
	}

	@Test
	public void raidWeightsScaleWithTheConfiguredUniqueChance()
	{
		DropTable.Source cox = dropTable.find("Chambers of Xeric");
		assertEquals(0.035 * 2 / 60, probabilityOf(cox, "Twisted bow", 0.035), 1.0e-12);
		assertEquals(0.035 * 14 / 60, probabilityOf(cox, "Dexterous prayer scroll", 0.035), 1.0e-12);
	}

	/** A typo in the data file would otherwise quietly hand out free luck. */
	@Test
	public void everySourceProducesUsableProbabilities()
	{
		for (DropTable.Source source : dropTable.getSources())
		{
			assertTrue(source.getName() + " has no items", !source.getItems().isEmpty());

			for (DropTable.Variant variant : source.getVariants())
			{
				double weightSum = 0;

				for (DropTable.Item item : variant.getItems())
				{
					double p = DropTable.probability(variant, item, 0.05);

					assertTrue(source.getName() + " / " + item.getName() + " has no rate", p > 0);
					assertTrue(source.getName() + " / " + item.getName() + " is not a probability", p <= 1);

					if (item.weight != null)
					{
						assertNotNull(source.getName() + " uses weights without a totalWeight", variant.totalWeight);
						weightSum += item.weight;
					}
				}

				if (variant.totalWeight != null)
				{
					assertEquals(source.getName() + " weights do not sum to totalWeight",
						variant.totalWeight, weightSum, 1.0e-9);
				}
			}
		}
	}

	/** Counter labels keep their brackets, or the two Chambers counters become the same key. */
	@Test
	public void counterNormalisationKeepsTheModeApart()
	{
		assertEquals("chambers of xeric completions",
			DropTable.normaliseCounter("Chambers of Xeric completions"));
		assertEquals("chambers of xeric cm completions",
			DropTable.normaliseCounter("Chambers of Xeric (CM) completions"));
		assertNotEquals(DropTable.normaliseCounter("Theatre of Blood completions"),
			DropTable.normaliseCounter("Theatre of Blood (Hard) completions"));
	}

	private static double probabilityOf(DropTable.Source source, String itemName, double uniqueChance)
	{
		for (DropTable.Variant variant : source.getVariants())
		{
			for (DropTable.Item item : variant.getItems())
			{
				if (DropTable.normalise(item.getName()).equals(DropTable.normalise(itemName)))
				{
					return DropTable.probability(variant, item, uniqueChance);
				}
			}
		}

		throw new AssertionError("No such item: " + itemName);
	}
}

package com.spoonmeter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class LuckCalculatorTest
{
	private static final double DELTA = 1.0e-6;

	@Test
	public void poissonPmfMatchesKnownValues()
	{
		assertEquals(Math.exp(-1), LuckCalculator.poissonPmf(0, 1), DELTA);
		assertEquals(0.19536681, LuckCalculator.poissonPmf(4, 4), 1.0e-6);
		assertEquals(0.12511003, LuckCalculator.poissonPmf(10, 10), 1.0e-6);
	}

	@Test
	public void poissonCdfMatchesKnownValues()
	{
		assertEquals(0.36787944, LuckCalculator.poissonCdf(0, 1), 1.0e-6);
		assertEquals(0.43347012, LuckCalculator.poissonCdf(3, 4), 1.0e-6);
		assertEquals(0.58303975, LuckCalculator.poissonCdf(10, 10), 1.0e-6);
	}

	/** The continued fraction branch has to stay sane where a naive sum would not. */
	@Test
	public void poissonCdfIsStableAtLargeLambda()
	{
		assertEquals(0.5, LuckCalculator.poissonCdf(5000, 5000), 0.01);
		assertTrue(LuckCalculator.poissonCdf(4000, 5000) < 1.0e-6);
		assertTrue(LuckCalculator.poissonCdf(6000, 5000) > 0.999999);
	}

	@Test
	public void averageAccountScoresAroundFifty()
	{
		double percentile = LuckCalculator.luckPercentile(30.0, 30);
		assertEquals(0.5, percentile, 0.05);
	}

	@Test
	public void moreUniquesIsAlwaysLuckier()
	{
		double previous = -1;

		for (int obtained = 0; obtained <= 40; obtained++)
		{
			double percentile = LuckCalculator.luckPercentile(20.0, obtained);
			assertTrue("percentile should increase with uniques", percentile > previous);
			previous = percentile;
		}
	}

	@Test
	public void spoonedAndCursedEndsAreExtreme()
	{
		assertTrue(LuckCalculator.luckPercentile(10.0, 0) < 0.001);
		assertTrue(LuckCalculator.luckPercentile(10.0, 25) > 0.99);
	}

	@Test
	public void drynessIsTheChanceYouShouldHaveItByNow()
	{
		assertEquals(0.0, LuckCalculator.dryness(0.01, 0), DELTA);
		assertEquals(0.63396766, LuckCalculator.dryness(0.01, 100), 1.0e-6);
		assertEquals(0.99995482, LuckCalculator.dryness(1.0 / 1024, 10240), 1.0e-6);
	}

	@Test
	public void noDataIsNeitherLuckyNorUnlucky()
	{
		assertEquals(0.5, LuckCalculator.luckPercentile(0, 0), DELTA);
	}

	@Test
	public void ratingBandsFollowThePercentile()
	{
		assertEquals(LuckRating.SPOONED_BY_THE_GODS, LuckRating.fromPercentile(0.999));
		assertEquals(LuckRating.AVERAGE, LuckRating.fromPercentile(0.5));
		assertEquals(LuckRating.RNG_HATES_YOU, LuckRating.fromPercentile(0.002));
		assertEquals(50, LuckRating.spoonScore(0.5));
	}
}

package com.spoonmeter;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

/**
 * The same checks as the JUnit tests, with no JUnit.
 *
 * <p>Building this plugin without Gradle means there is no test framework on the classpath, so this
 * runs the maths, the drop table and the rating pipeline from a plain {@code main} and reports what
 * failed. Run it with {@code build.ps1 -Verify}.
 */
public class SelfCheck
{
	private static int checks;
	private static int failures;

	public static void main(String[] args) throws Exception
	{
		DropTable dropTable = DropTable.load(new Gson(), null);

		poissonMaths();
		headerParsing();
		dropTableIntegrity(dropTable);
		ratingPipeline(dropTable);
		splitPages(dropTable);
		chatLines(dropTable);
		sharedItems(dropTable);
		sharedSlots(dropTable);
		perBossRates(dropTable);
		hidingCombinedPages(dropTable);
		hidingBosses(dropTable);
		effectiveRates(dropTable);
		accountScore(dropTable);
		rarityNotJustCount(dropTable);
		sharedAndCountedRolls(dropTable);

		System.out.println();
		System.out.println(checks + " checks, " + failures + " failed");
		System.exit(failures == 0 ? 0 : 1);
	}

	private static void poissonMaths()
	{
		section("Poisson / incomplete gamma");

		near("pmf(0, 1)", Math.exp(-1), LuckCalculator.poissonPmf(0, 1), 1e-9);
		near("pmf(4, 4)", 0.19536681, LuckCalculator.poissonPmf(4, 4), 1e-6);
		near("pmf(10, 10)", 0.12511003, LuckCalculator.poissonPmf(10, 10), 1e-6);
		near("cdf(0, 1)", 0.36787944, LuckCalculator.poissonCdf(0, 1), 1e-6);
		near("cdf(3, 4)", 0.43347012, LuckCalculator.poissonCdf(3, 4), 1e-6);
		near("cdf(10, 10)", 0.58303975, LuckCalculator.poissonCdf(10, 10), 1e-6);

		// The continued fraction branch has to hold up where a naive sum would not.
		near("cdf(5000, 5000)", 0.5, LuckCalculator.poissonCdf(5000, 5000), 0.01);
		check("cdf(4000, 5000) is tiny", LuckCalculator.poissonCdf(4000, 5000) < 1e-6);
		check("cdf(6000, 5000) is ~1", LuckCalculator.poissonCdf(6000, 5000) > 0.999999);

		near("average account sits near 0.5", 0.5, LuckCalculator.luckPercentile(30.0, 30), 0.05);
		near("no data is 0.5", 0.5, LuckCalculator.luckPercentile(0, 0), 1e-9);
		check("0 of 10 expected is bottom 0.1%", LuckCalculator.luckPercentile(10.0, 0) < 0.001);
		check("25 of 10 expected is top 1%", LuckCalculator.luckPercentile(10.0, 25) > 0.99);

		double previous = -1;
		boolean monotonic = true;

		for (int obtained = 0; obtained <= 40; obtained++)
		{
			double percentile = LuckCalculator.luckPercentile(20.0, obtained);
			monotonic &= percentile > previous;
			previous = percentile;
		}

		check("more uniques is always luckier", monotonic);

		near("dryness(1/100, 100)", 0.63396766, LuckCalculator.dryness(0.01, 100), 1e-6);
		near("dryness(1/1024, 10240)", 0.99995482, LuckCalculator.dryness(1.0 / 1024, 10240), 1e-6);

		check("0.999 is spooned", LuckRating.fromPercentile(0.999) == LuckRating.SPOONED_BY_THE_GODS);
		check("0.5 is average", LuckRating.fromPercentile(0.5) == LuckRating.AVERAGE);
		check("0.002 is a war crime", LuckRating.fromPercentile(0.002) == LuckRating.RNG_HATES_YOU);
	}

	private static void headerParsing()
	{
		section("Collection log header parsing");

		Map<String, Integer> counters = new LinkedHashMap<>();

		// "Personal Best: 9:51" read as a counter named "Personal Best: 9" worth 51 beat the real
		// kill count on any page with fewer kills than that - Vorkath at 10 kills scored as 29.
		check("personal best times are not counters",
			!CollectionLogParser.addCounter(counters, "Personal Best: 9:51"));
		check("nor corrupted personal bests",
			!CollectionLogParser.addCounter(counters, "Personal Best Corrupted: 7:56"));
		check("real counters still parse",
			CollectionLogParser.addCounter(counters, "Corrupted Gauntlet completion count: 1,487"));
		check("with thousands separators", counters.get("Corrupted Gauntlet completion count") == 1487);
		check("and nothing else got in", counters.size() == 1);
	}

	private static void splitPages(DropTable dropTable)
	{
		section("Pages with several counters");

		Map<String, Double> chances = new HashMap<>();
		chances.put("cox", 0.035);
		chances.put("coxcm", 0.05);
		chances.put("tob", 0.037);
		chances.put("tobhm", 0.044);
		chances.put("toa", 0.12);
		chances.put("toaexpert", 0.15);

		CollectionLogPage gauntlet = gauntletPage();

		SpoonReport report = SpoonReport.build(Collections.singletonList(gauntlet), dropTable, chances, 10);
		SpoonReport.SourceLine line = report.getSources().get(0);

		near("both Gauntlet counters are added up", 1498, line.getKc(), 0);
		near("and both rate tables are blended", 65.25, line.getExpected(), 0.05);
		check("the cape is not counted as a drop", line.getObtained() == 52);
		check("52 uniques against 65 expected reads as dry", line.getPercentile() < 0.10);
		check("which lands at the cursed end, not the spooned one",
			line.getRating() == LuckRating.CURSED || line.getRating() == LuckRating.HARD_CURSED
				|| line.getRating() == LuckRating.RNG_HATES_YOU);

		CollectionLogPage kings = new CollectionLogPage("Dagannoth Kings");
		kings.getCounters().put("Dagannoth Rex kills", 70);
		kings.getCounters().put("Dagannoth Prime kills", 0);
		kings.getCounters().put("Dagannoth Supreme kills", 0);

		SpoonReport dks = SpoonReport.build(Collections.singletonList(kings), dropTable, chances, 10);

		check("Dagannoth Kings is one page, not three", !dks.isEmpty());
		near("and only the king you fought counts", 1.65, dks.getExpected(), 0.01);

